// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Setup a token contract address to call (we'll use a simple mock)
        // Since C.transfer calls transferFrom on caddress, we need a contract that responds positively to any call
        // To avoid complexity, we test the revert itself by using a dummy address that will fail the inner call — but the outer require(_tos.length == 0) in M reverts before even reaching that call.
        // So we just need _tos array with length >0 to trigger the revert in M.
        address[] memory tos = new address[](1);
        tos[0] = address(1);
        uint[] memory vals = new uint[](1);
        vals[0] = 1;
        bool ok;
        try c.transfer(address(0), address(0xdead), tos, vals) { ok = true; } catch { ok = false; }
        // On reference C, transfer succeeds (returns true), so ok = true.
        // On buggy M, require(_tos.length == 0) fails because _tos.length is 1, so it reverts, and ok = false.
        assertTrue(ok);
    }
}
